  "bio": "<p>هوميروس هو الاسم الذي أطلقته التقاليد اليونانية على شاعر <em>الإلياذة</em> و<em>الأوديسة</em>، اللتين نُظمتا غالبًا في القرن 8 قبل الميلاد في إيونيا. لا يُعرف عن حياته شيء يقيني تقريبًا: فقد تنازعت مدن عدة، مثل سميرنا وخيوس، على أنها مسقط رأسه، وتقول التقاليد إنه كان منشدًا أعمى. ويرى كثير من الدارسين أن القصيدتين تجمعان تراثًا شفويًا طويلًا دوّنه أحدهم كتابةً، وهذه هي المسألة الهوميرية المعروفة.</p>\n<p>كانت قصائده أساس التربية اليونانية: ففيها كان الناس يتعلمون <strong>الأريتي</strong> (areté، أي التميّز) عند البطل، ويتعرفون على الآلهة التي تتصرف بانفعالات بشرية وتقرر مصير البشر الفانين. ولهذا يرد في المقرر مثالًا على <strong>التفكير الأسطوري</strong> الذي ثار عليه أوائل الفلاسفة، وهدفًا لنقد كزينوفانس.</p>",
