  "role": "مشرّع وشاعر أثيني",
  "idea": "بإصلاحاته ألغى الديون، ومنع الاسترقاق بسبب الديون، ووزّع الحقوق السياسية بحسب الثروة، فمهّد الطريق للديمقراطية الأثينية.",
  "bio": "<p>كان سولون سياسيًا ومشرّعًا وشاعرًا أثينيًا. وُلد حوالي 640 ق.م في أسرة نبيلة، وعدّه اليونانيون من الحكماء السبعة. وفي حوالي 594 ق.م انتخبه الأثينيون أرخونًا، أي كبير قضاة المدينة، في عزّ أزمة اجتماعية: إذ خسر كثير من الفلاحين المدينين أراضيهم أو تحوّلوا إلى عبيد. ودافع عن إصلاحاته في قصائد وصلتنا منها مقاطع.</p>\n<p>بـ<strong>السيساختيا (seisachtheia)</strong> (أي نزع الأعباء) ألغى الديون ومنع استرقاق الإنسان بسبب دَين. ووزّع الحقوق السياسية بحسب الثروة لا بحسب النسب، وفتح الجمعية والمحاكم أمام جميع المواطنين. ويظهر في المقرر لأن إصلاحاته، مع إصلاحات كليسثينيس، مهّدت <strong>الديمقراطية</strong> الأثينية في القرن 5 ق.م.</p>",
  "obras": [
   "المراثي (شذرات)"
  ],
  "anecdota": "<p>يروي هيرودوت أنّ سولون زار في أثناء أسفاره كروسوس، ملك ليديا المشهور بثرواته، في ساردس. وبعد أن عرض عليه كنوزه، سأله كروسوس: من هو أسعد رجل عرفه؟ وكان يتوقع أن يسمع اسمه هو. فذكر سولون أثينيًا بسيطًا اسمه تيلوس، رأى أبناءه يكبرون ومات مكرَّمًا وهو يدافع عن مدينته. وأضاف أنه لا يمكن أن يُقال عن أحد إنه سعيد ما دام حيًّا، لأن الحظ يتغيّر. صرفه كروسوس باحتقار، لكنه سيتذكّر كلماته لاحقًا بعد أن فقد مملكته. غير أنّ التسلسل الزمني يجعلنا نشكّ في أن اللقاء قد حدث فعلًا.</p>",
