  "role": "فيلسوف ما قبل سقراط",
  "idea": "مبدأ كل شيء هو الهواء، الذي يصير نارًا بالتخلخل، ويصير ريحًا وغيومًا وماءً وترابًا وحجرًا بالتكاثف.",
  "bio": "<p>كان أنكسيمانس ثالث مفكر كبير في ميليتوس، وتلميذًا لأنكسيمندريس أو رفيقًا له. عاش في القرن 6 قبل الميلاد، في زمن وقعت فيه المدن الإيونية تحت سيطرة الفرس. كتب كتابًا بنثر بسيط لم يبق منه إلا سطور قليلة؛ ونعرف أفكاره خصوصًا من أرسطو ومن شرّاحه.</p>\n<p>عنده، <strong>المبدأ الأول</strong> (arkhé) هو <strong>الهواء</strong>: لا يُرى، لكنه حاضر في التجربة، وغير متناهٍ وفي حركة دائمة. وهكذا يتوسط بين سلفيه: مثل طاليس يختار عنصرًا طبيعيًا، ومثل أنكسيمندريس يختار عنصرًا غير متناهٍ. وإسهامه الكبير هو تفسير كيفية تكوّن الأشياء: بـ<strong>التخلخل</strong> يسخن الهواء ويصير نارًا؛ وبـ<strong>التكاثف</strong> يبرد ويصير ريحًا وغيومًا وماءً وترابًا وحجرًا. أي أن اختلاف الصفات يُفسَّر باختلاف الكثافة.</p>\n<p>كان يشبّه الهواء الذي يحيط بالكون بالنفس، فالنفس هواء ويُبقي الجسد حيًا: وهذا مثال على <strong>الهيلوزوئية</strong> (hilozoísmo)، أي فكرة أن المادة حيّة. واقتراحه تفسير التغيرات بآلية طبيعية، تكاد تكون كمية، يستبق العلم اللاحق. وبه تُختتم مدرسة ميليتوس؛ وبعده ينتقل التفكير في المبدأ الأول إلى مدن أخرى، من أفسس إلى بلاد اليونان الكبرى.</p>",
