  "role": "فيلسوف سويدي",
  "idea": "إذا استطاعت الحضارات المتقدمة أن تحاكي عوالم فيها كائنات واعية، وقررت أن تفعل ذلك، فمن المرجح أننا نعيش نحن أنفسنا في محاكاة حاسوبية.",
  "bio": "<p>وُلد نيك بوستروم في هلسنبورغ (السويد) سنة 1973. درس الفلسفة والفيزياء والعلوم العصبية الحاسوبية، ونال الدكتوراه من كلية لندن للاقتصاد. وكان أستاذًا في جامعة أكسفورد، حيث أدار معهد مستقبل الإنسانية، المخصص للأخطار التي تهدد النوع البشري.</p>\n<p>في سنة 2003 صاغ <strong>حجة المحاكاة</strong>. فحسب رأيه، واحد على الأقل من هذه الاحتمالات الثلاثة صحيح: لا تكاد توجد حضارة تصل إلى تكنولوجيا قادرة على محاكاة عقول واعية؛ أو أنّ الحضارات التي تصل إليها لا تريد ذلك؛ أو أننا على الأرجح نعيش في <strong>محاكاة</strong>. وهو موجود في المقرر لأنّ فرضيته تذكّر بـ<strong>الشيطان الماكر</strong> عند ديكارت. كما اشتهر بدراساته حول أخطار الذكاء الاصطناعي.</p>",
